 const cleaned={grants:await all(db,"SELECT id,staff_id,permission,effect,scope_kind,business_area_id,division_id,resource_id,active,granted_by,created_at FROM native_directory_grants WHERE id IN (?,?) ORDER BY id",...grantIds),grantGeneration:await first(db,"SELECT generation FROM native_directory_grant_generations WHERE staff_id=?",scalarTarget.staffId).then(row=>row.generation),grantHistory:await all(db,"SELECT grant_id,grant_version,staff_id,permission,effect,scope_kind,business_area_id,division_id,resource_id,active,grant_generation FROM native_directory_grant_history WHERE grant_id IN (?,?) ORDER BY grant_id,grant_version",...grantIds),settlementSnapshot:{plan:structuredClone(plan),before:structuredClone(scalarPrestate.before),settled:await scalarSnapshot(db)},protectedSnapshots:cleanedProtected};
 assert.deepEqual(cleanedProtected,acknowledged.protectedSnapshots,"cleanup must independently recapture and preserve protected authority state");
 assert.equal(validatePairedGrantCleanup({settlement,acknowledged,cleaned}).status,"cleaned");
 assert.deepEqual(cleaned.grants.map(row=>row.active),[0,0]);
